/**
 * The over-the-air UI's files and state. Versions live in {@code no_backup/denext-ota/<version>/}
 * (never in a device backup: a UI is re-downloadable), the state in SharedPreferences:
 *
 * <ul>
 *   <li>{@code current}: the confirmed downloaded version (null: the bundled {@code public/} UI).
 *   <li>{@code pending} / {@code previous}: a version on its trial launch, and what {@code current}
 *       was before it.
 *   <li>{@code trialAttempts}: how many launches the pending version has had without confirming its
 *       boot. A launch that finds {@link #MAX_TRIAL_ATTEMPTS} used rolls the version back unseen, so
 *       one process death does not reject a good UI, but a UI that kills the app every time is
 *       rolled back on the launch after its second try.
 *   <li>{@code rejected}: the last version rolled back; {@code apply} refuses it (code
 *       {@code rejected}) until {@code reset}, so a broken server UI cannot put the app in an
 *       apply → rollback loop.
 *   <li>{@code staged}: a version {@code download} verified into its directory, waiting for
 *       {@code activate}. It is never started on its own: launch only ever serves {@code pending}
 *       or {@code current}.
 *   <li>{@code sequence}: the highest manifest {@code sequence} accepted on this device. A lower
 *       one, or none once any was accepted, is refused (code {@code downgrade}). It survives
 *       {@code reset} and new binaries: only clearing the app's data resets it.
 *   <li>{@code binaryVersion}: the app binary the downloads belong to. A new binary brings its
 *       own bundled UI (and maybe new native code), so every download is dropped.
 *   <li>{@code tampered}: the last downloaded version that failed re-verification (see
 *       {@link #admit}) and was taken out of service, until {@code reset}.
 * </ul>
 *
 * <p>A downloaded UI is verified when it arrives, and again whenever it is served: every launch
 * (and the first request of a UI switched to while running) checks the manifest stored with its
 * files (the signature with the embedded key, and the version recomputed from the file list), and
 * {@link Routes}, the bridge's route processor, checks each file's SHA-256 and size against that
 * manifest the first time it serves it in a process. A file changed, added or removed on the
 * device after the download is never served: the version is moved to {@code quarantine/}, the app
 * falls back to its bundled UI (or the confirmed one, re-verified), and the page hears
 * {@code otaRejected}.
 *
 * <p>State transitions are synchronized; {@link #download} runs off the main thread, and every
 * recursive delete runs on a background thread after a rename.
 */
final class DenextOtaStore {

    /** The {@code <meta-data>} holding the boot timeout in seconds (default 15, 1 … 600). */
    static final String BOOT_TIMEOUT_META = "dev.denext.ota.BOOT_TIMEOUT";
    /** Launches a pending version gets before it is rolled back unseen. */
    static final int MAX_TRIAL_ATTEMPTS = 2;
    /** The most files a manifest may list. */
    static final int MAX_FILES = 20_000;
    /** The most bytes a manifest's files may add up to (512 MiB). */
    static final long MAX_TOTAL_BYTES = 512L * 1024 * 1024;
    /** The longest a whole download / apply may take before it is cancelled. */
    static final long APPLY_DEADLINE_MS = 30L * 60 * 1000;
    /** The bundled UI's asset directory (Bridge.DEFAULT_WEB_ASSET_DIR). */
    static final String BUNDLED_ASSET_DIR = "public";
    /** The manifest inside a UI directory, as {@code denext export} and {@code denext ota manifest} write it. */
    static final String MANIFEST_PATH = "_denext/ota.json";

    private static final String PREFS = "denext.ota";
    private static final String KEY_CURRENT = "current";
    private static final String KEY_PENDING = "pending";
    private static final String KEY_PREVIOUS = "previous";
    /** Written by earlier templates; cleared wherever the trial state is. */
    private static final String KEY_LEGACY_TRIAL_STARTED = "trialStarted";
    private static final String KEY_TRIAL_ATTEMPTS = "trialAttempts";
    private static final String KEY_REJECTED = "rejected";
    private static final String KEY_STAGED = "staged";
    private static final String KEY_SEQUENCE = "sequence";
    private static final String KEY_BINARY_VERSION = "binaryVersion";
    private static final String KEY_TAMPERED = "tampered";
    /** Where a version that failed re-verification is moved (only the latest is kept). */
    private static final String QUARANTINE_DIR = "quarantine";
    private static final String TRASH_PREFIX = ".denext-ota-trash-";
    private static final int MAX_CONCURRENT_DOWNLOADS = 6;
    /** The longest a download may go without receiving a byte. */
    private static final int IDLE_TIMEOUT_MS = 30_000;
    private static final int MAX_REDIRECTS = 5;
    /**
     * The {@code <meta-data>} (inside {@code <application>}) holding the OTA public key: base64 of
     * the DER SubjectPublicKeyInfo of an ECDSA P-256 key ({@code denext mobile add-ota --public-key}).
     * Read from the app binary only.
     */
    static final String PUBLIC_KEY_META = "dev.denext.ota.PUBLIC_KEY";
    /**
     * The {@code <meta-data>} (inside {@code <application>}) holding this binary's native
     * fingerprint ({@code denext mobile fingerprint --write}).
     */
    static final String NATIVE_FINGERPRINT_META = "dev.denext.native.FINGERPRINT";
    /** The group order n of NIST P-256 (secp256r1), which identifies the curve of a parsed key. */
    private static final BigInteger P256_ORDER = new BigInteger(
        "FFFFFFFF00000000FFFFFFFFFFFFFFFFBCE6FAADA7179E84F3B9CAC2FC632551",
        16
    );
    /** The hosts an unsigned UI may come from over plain http when no public key is embedded. */
    static final Set<String> LOOPBACK_HOSTS = new HashSet<>(Arrays.asList("localhost", "127.0.0.1", "::1", "[::1]"));
    /** The emulator's alias for the host machine: loopback too, but only in a debuggable build. */
    static final String EMULATOR_HOST = "10.0.2.2";
    /**
     * The {@code <meta-data>} (inside {@code <application>}) pinning the origins a UI may come from
     * (space- or comma-separated, {@code denext mobile add-ota --ota-origin}). Read from the app
     * binary only.
     */
    static final String ORIGINS_META = "dev.denext.ota.ORIGINS";

    /** Deletes discarded directories off the main thread. */
    private static final ExecutorService JANITOR = Executors.newSingleThreadExecutor((runnable) -> {
        Thread thread = new Thread(runnable, "denext-ota-janitor");
        thread.setDaemon(true);
        return thread;
    });

    private static DenextOtaStore shared;

    /** Set by {@link DenextOta#prepare} when this launch is a pending version's trial; the plugin arms the watchdog. */
    static volatile boolean launchIsTrial = false;

    static synchronized DenextOtaStore get(Context context) {
        if (shared == null) {
            shared = new DenextOtaStore(context.getApplicationContext());
        }
        return shared;
    }

    /** The longest one file may take: 30 s, plus what a 32 KiB/s link needs for its size. */
    static long fileDeadlineMs(long size) {
        return 30_000 + size * 1000 / 32_768;
    }

    /** The {@link OtaException} code for a file of a downloaded UI that is there but cannot be read right now. */
    static final String UNAVAILABLE = "unavailable";

    static final class OtaException extends Exception {

        final String code;

        OtaException(String code, String message) {
            super(message);
            this.code = code;
        }
    }

    static final class ManifestFile {

        final String path;
        final String sha256;
        final long size;

        ManifestFile(String path, String sha256, long size) {
            this.path = path;
            this.sha256 = sha256;
            this.size = size;
        }
    }

    static final class ApplyRequest {

        final String baseUrl;
        final Map<String, String> headers;
        final String version;
        final List<ManifestFile> files;
        @Nullable
        final Long sequence;
        /** The rest of what the signature covers, stored with the files so every launch can verify it again. */
        final boolean required;
        final String notes;
        @Nullable
        final Long minNative;
        @Nullable
        final String nativeFingerprint;
        @Nullable
        final String signature;

        ApplyRequest(
            String baseUrl,
            Map<String, String> headers,
            String version,
            List<ManifestFile> files,
            @Nullable Long sequence,
            boolean required,
            String notes,
            @Nullable Long minNative,
            @Nullable String nativeFingerprint,
            @Nullable String signature
        ) {
            this.baseUrl = baseUrl;
            this.headers = headers;
            this.version = version;
            this.files = files;
            this.sequence = sequence;
            this.required = required;
            this.notes = notes;
            this.minNative = minNative;
            this.nativeFingerprint = nativeFingerprint;
            this.signature = signature;
        }
    }

    /** What {@link #download} did: files fetched over the network, and files copied from the device. */
    static final class DownloadStats {

        int downloaded = 0;
        int copied = 0;
    }

    /** A UI already on the device that files can be copied from. */
    private interface LocalSource {
        /** The bytes at {@code path} inside this UI, or null. {@code path} is already validated. */
        @Nullable
        InputStream open(String path);

        /** SHA-256 → path, from this UI's own manifest. */
        Map<String, String> pathsBySha();
    }

    private final Context context;
    private final SharedPreferences prefs;
    final File root;
    @Nullable
    private String bundledVersion;
    private boolean bundledVersionRead = false;
    private boolean launchPrepared = false;
    /** Set by {@link #cancelDownload}; the download in flight stops at its next check. */
    private volatile boolean cancelRequested = false;
    /** The connections of the download in flight, so a cancel can unblock their reads. */
    private final Set<HttpURLConnection> connections = Collections.synchronizedSet(new HashSet<>());

    private DenextOtaStore(Context context) {
        this.context = context;
        this.prefs = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE);
        this.root = new File(context.getNoBackupFilesDir(), "denext-ota");
        migrateLegacyRoot();
        sweepTrash(root.getParentFile());
        sweepTrash(root);
    }

    /**
     * Earlier templates kept the versions in {@code files/denext-ota} (which a device backup may
     * include). Move them to {@code no_backup/}; when that fails, drop them and forget every
     * version they held, so the app starts from its bundled UI and downloads again.
     */
    private void migrateLegacyRoot() {
        File legacy = new File(context.getFilesDir(), "denext-ota");
        if (!legacy.exists()) {
            return;
        }
        if (root.exists()) {
            // Already migrated (the old directory reappeared somehow): it holds nothing in use.
            discard(legacy);
            return;
        }
        if (legacy.renameTo(root)) {
            return;
        }
        prefs
            .edit()
            .remove(KEY_CURRENT)
            .remove(KEY_PENDING)
            .remove(KEY_PREVIOUS)
            .remove(KEY_STAGED)
            .remove(KEY_TRIAL_ATTEMPTS)
            .remove(KEY_LEGACY_TRIAL_STARTED)
            .commit();
        discard(legacy);
    }

    /** The boot timeout in ms, from {@link #BOOT_TIMEOUT_META} (seconds) or 15 s. */
    long bootTimeoutMs() {
        double seconds = 15;
        try {
            ApplicationInfo info = context.getPackageManager().getApplicationInfo(context.getPackageName(), PackageManager.GET_META_DATA);
            Object value = info.metaData == null ? null : info.metaData.get(BOOT_TIMEOUT_META);
            if (value instanceof Number) {
                seconds = ((Number) value).doubleValue();
            } else if (value instanceof String) {
                seconds = Double.parseDouble(((String) value).trim());
            }
        } catch (PackageManager.NameNotFoundException | NumberFormatException ex) {
            seconds = 15;
        }
        return (long) (Math.min(Math.max(seconds, 1), 600) * 1000);
    }

    /** Whether {@code value} is 64 lowercase ASCII hex digits. */
    static boolean isSha256(@Nullable String value) {
        return value != null && value.matches("[0-9a-f]{64}");
    }

    /**
     * The manifest version of {@code files}: SHA-256 over the {@code "<path>\t<sha256>\n"} lines
     * sorted by path ({@link String#compareTo} is UTF-16 code-unit order, as in denext's
     * {@code otaManifestVersion}).
     */
    static String manifestVersion(List<ManifestFile> files) {
        List<ManifestFile> sorted = new ArrayList<>(files);
        Collections.sort(sorted, (a, b) -> a.path.compareTo(b.path));
        StringBuilder lines = new StringBuilder();
        for (ManifestFile file : sorted) {
            lines.append(file.path).append('\t').append(file.sha256).append('\n');
        }
        return sha256Hex(lines.toString().getBytes(StandardCharsets.UTF_8));
    }

    /**
     * The manifest's {@code files}, checked one by one and against the caps (code invalid): a safe
     * path (not the manifest itself, no duplicates), a SHA-256, an integer size, at most
     * {@link #MAX_FILES} files and {@link #MAX_TOTAL_BYTES} bytes, and an index.html.
     */
    static List<ManifestFile> parseFiles(@Nullable JSONArray rawFiles) throws OtaException {
        if (rawFiles == null || rawFiles.length() == 0) {
            throw new OtaException("invalid", "The manifest is malformed.");
        }
        if (rawFiles.length() > MAX_FILES) {
            throw new OtaException("invalid", "The manifest lists more than " + MAX_FILES + " files.");
        }
        List<ManifestFile> files = new ArrayList<>();
        Set<String> seen = new HashSet<>();
        long total = 0;
        for (int index = 0; index < rawFiles.length(); index++) {
            JSONObject file = rawFiles.optJSONObject(index);
            Object path = file == null ? null : file.opt("path");
            Object sha256 = file == null ? null : file.opt("sha256");
            Long size = file == null ? null : releaseInteger(file.opt("size"), "size");
            if (
                !(path instanceof String) ||
                !isSafeRelativePath((String) path) ||
                path.equals(MANIFEST_PATH) ||
                !seen.add((String) path) ||
                !(sha256 instanceof String) ||
                !isSha256((String) sha256) ||
                size == null
            ) {
                throw new OtaException("invalid", "The manifest lists a malformed file.");
            }
            total += size;
            if (total > MAX_TOTAL_BYTES) {
                throw new OtaException("invalid", "The manifest's files add up to more than " + MAX_TOTAL_BYTES + " bytes.");
            }
            files.add(new ManifestFile((String) path, (String) sha256, size));
        }
        if (!seen.contains("index.html")) {
            throw new OtaException("invalid", "The manifest has no index.html.");
        }
        return files;
    }

    /** A JSON integer in 0 … 2^53 − 1 (null when absent); anything else is code invalid. */
    @Nullable
    static Long releaseInteger(@Nullable Object value, String name) throws OtaException {
        if (value == null || value == JSONObject.NULL) {
            return null;
        }
        if (value instanceof Number) {
            double number = ((Number) value).doubleValue();
            if (number >= 0 && number <= 9_007_199_254_740_991.0 && number == Math.rint(number)) {
                return ((Number) value).longValue();
            }
        }
        throw new OtaException("invalid", "The manifest's " + name + " is not a non-negative integer.");
    }

    /** The manifest's nativeFingerprint: null when absent, else 64 lowercase hex digits (else invalid). */
    @Nullable
    static String fingerprintField(@Nullable Object value) throws OtaException {
        if (value == null || value == JSONObject.NULL) {
            return null;
        }
        if (value instanceof String && isSha256((String) value)) {
            return (String) value;
        }
        throw new OtaException("invalid", "The manifest's nativeFingerprint is not 64 lowercase hex digits.");
    }

    /**
     * The bytes a manifest signature covers (denext's {@code otaSignaturePayload}), UTF-8 with
     * {@code \n} separators and no trailing newline. With a {@code sequence} and a
     * {@code nativeFingerprint} (v3): {@code "denext-ota-v3\n" + version + "\n" + ("1" | "0") +
     * "\n" + sha256hex(notes) + "\n" + sequence + "\n" + (minNative or "") + "\n" +
     * nativeFingerprint}; with a {@code sequence} alone (v2):
     * {@code "denext-ota-v2\n" + version + "\n" + ("1" | "0") + "\n" + sha256hex(notes) + "\n" +
     * sequence + "\n" + (minNative or "")}; without one (v1):
     * {@code "denext-ota-v1\n" + version + "\n" + ("1" | "0") + "\n" + sha256hex(notes)}.
     */
    static byte[] signaturePayload(
        String version,
        boolean required,
        String notes,
        @Nullable Long sequence,
        @Nullable Long minNative,
        @Nullable String nativeFingerprint
    ) {
        String head = version + "\n" + (required ? "1" : "0") + "\n" + sha256Hex(notes.getBytes(StandardCharsets.UTF_8));
        String text;
        if (sequence == null) {
            text = "denext-ota-v1\n" + head;
        } else {
            String v2 = head + "\n" + sequence + "\n" + (minNative == null ? "" : String.valueOf(minNative));
            text = nativeFingerprint == null ? "denext-ota-v2\n" + v2 : "denext-ota-v3\n" + v2 + "\n" + nativeFingerprint;
        }
        return text.getBytes(StandardCharsets.UTF_8);
    }

    /**
     * The download policy, checked before any file is fetched. With a public key embedded, the
     * manifest must carry a valid signature over {@code payload} (code signature), whatever the
     * transport; a key that is present but does not parse refuses every manifest. Without one,
     * only https, or plain http to a loopback host, is allowed (code insecure); the emulator's
     * {@code 10.0.2.2} counts as loopback only in a debuggable build. A signature protects
     * integrity only: over plain http the request headers (bearer tokens) cross the network in
     * the clear.
     */
    void checkTrust(Uri base, byte[] payload, @Nullable String signature) throws OtaException {
        String host = base.getHost() == null ? "" : base.getHost().toLowerCase(Locale.ROOT);
        boolean loopback = LOOPBACK_HOSTS.contains(host) || (EMULATOR_HOST.equals(host) && isDebuggable());
        List<Uri> pins = pinnedOrigins();
        boolean pinned = isPinnedOrigin(pins, base);
        if (!pins.isEmpty() && !pinned && !loopback) {
            throw new OtaException("insecure", "Refusing a UI from " + host + ": it is not one of the pinned " + ORIGINS_META + ".");
        }
        String encodedKey = publicKeyMetaData();
        if (encodedKey == null) {
            if (!(pinned && "https".equalsIgnoreCase(base.getScheme())) && !loopback) {
                throw new OtaException(
                    "insecure",
                    "Refusing an unsigned UI from " + host + "; embed a public key or pin its https origin (denext mobile add-ota --ota-origin)."
                );
            }
            return;
        }
        PublicKey key = parsePublicKey(encodedKey);
        if (key == null) {
            throw new OtaException("signature", "The " + PUBLIC_KEY_META + " meta-data is not a base64 P-256 public key.");
        }
        if (!isValidSignature(key, payload, signature)) {
            throw new OtaException("signature", "The manifest signature is missing or does not verify.");
        }
    }

    /**
     * The release policy, checked after {@link #checkTrust} (so a signed manifest's values are
     * authentic) and before any file is fetched: no {@code sequence} below the highest this device
     * accepted, and none missing once one was (code downgrade); no {@code minNative} above this
     * binary's {@code versionCode} (code native_too_old); no {@code nativeFingerprint} other than
     * this binary's (code native_mismatch), checked only when both carry one.
     */
    void checkRelease(@Nullable Long sequence, @Nullable Long minNative, @Nullable String nativeFingerprint) throws OtaException {
        Long highest = highestSequence();
        if (highest != null) {
            if (sequence == null) {
                throw new OtaException("downgrade", "The manifest has no sequence, but this device accepted sequence " + highest + ".");
            }
            if (sequence < highest) {
                throw new OtaException("downgrade", "The manifest's sequence " + sequence + " is older than " + highest + ".");
            }
        }
        long build = nativeBuild();
        if (minNative != null && minNative > build) {
            throw new OtaException("native_too_old", "This UI needs app build " + minNative + " or later; this is build " + build + ".");
        }
        String binary = binaryFingerprint();
        if (nativeFingerprint != null && binary != null && !nativeFingerprint.equals(binary)) {
            throw new OtaException(
                "native_mismatch",
                "This UI was built for native fingerprint " + nativeFingerprint.substring(0, 12) +
                    "; this app binary is " + binary.substring(0, 12) + "."
            );
        }
    }

    /**
     * This binary's native fingerprint (the {@link #NATIVE_FINGERPRINT_META} meta-data), which a
     * manifest's nativeFingerprint must equal; null when absent or not 64 hex digits, which skips
     * the check (as a manifest without one does).
     */
    @Nullable
    String binaryFingerprint() {
        try {
            ApplicationInfo info = context.getPackageManager().getApplicationInfo(context.getPackageName(), PackageManager.GET_META_DATA);
            Object value = info.metaData == null ? null : info.metaData.get(NATIVE_FINGERPRINT_META);
            String text = value == null ? "" : String.valueOf(value).trim().toLowerCase(Locale.ROOT);
            return isSha256(text) ? text : null;
        } catch (PackageManager.NameNotFoundException ex) {
            return null;
        }
    }

    /** The highest manifest {@code sequence} accepted on this device, or null. */
    @Nullable
    synchronized Long highestSequence() {
        return prefs.contains(KEY_SEQUENCE) ? prefs.getLong(KEY_SEQUENCE, 0) : null;
    }

    /** This binary's {@code versionCode}, which a manifest's {@code minNative} is compared with. */
    long nativeBuild() {
        try {
            return PackageInfoCompat.getLongVersionCode(context.getPackageManager().getPackageInfo(context.getPackageName(), 0));
        } catch (PackageManager.NameNotFoundException ex) {
            return 0;
        }
    }

    private boolean isDebuggable() {
        return (context.getApplicationInfo().flags & ApplicationInfo.FLAG_DEBUGGABLE) != 0;
    }

    /** The {@link #PUBLIC_KEY_META} value, or null when the app embeds none. */
    @Nullable
    /** The pinned origins ({@link #ORIGINS_META}); empty when none are pinned. */
    private List<Uri> pinnedOrigins() throws OtaException {
        ApplicationInfo info;
        try {
            info = context.getPackageManager().getApplicationInfo(context.getPackageName(), PackageManager.GET_META_DATA);
        } catch (PackageManager.NameNotFoundException ex) {
            throw new OtaException("insecure", "Could not read the app's meta-data.");
        }
        Object value = info.metaData == null ? null : info.metaData.get(ORIGINS_META);
        List<Uri> pins = new ArrayList<>();
        if (value == null) {
            return pins;
        }
        for (String part : String.valueOf(value).split("[\\s,]+")) {
            Uri pin = Uri.parse(part);
            if (!part.isEmpty() && pin.getScheme() != null && pin.getHost() != null) {
                pins.add(pin);
            }
        }
        return pins;
    }

    /** A URI's port, or its scheme's default (443 for https, else 80). */
    private static int effectivePort(Uri uri) {
        return uri.getPort() != -1 ? uri.getPort() : ("https".equalsIgnoreCase(uri.getScheme()) ? 443 : 80);
    }

    /** Whether {@code uri} is on one of {@code pins} (scheme, host and port). */
    static boolean isPinnedOrigin(List<Uri> pins, Uri uri) {
        for (Uri pin : pins) {
            if (pin.getScheme().equalsIgnoreCase(String.valueOf(uri.getScheme()))
                && pin.getHost().equalsIgnoreCase(String.valueOf(uri.getHost()))
                && effectivePort(pin) == effectivePort(uri)) {
                return true;
            }
        }
        return false;
    }

    private String publicKeyMetaData() throws OtaException {
        ApplicationInfo info;
        try {
            info = context.getPackageManager().getApplicationInfo(context.getPackageName(), PackageManager.GET_META_DATA);
        } catch (PackageManager.NameNotFoundException ex) {
            throw new OtaException("signature", "Could not read the app's meta-data.");
        }
        Object value = info.metaData == null ? null : info.metaData.get(PUBLIC_KEY_META);
        if (value == null) {
            return null;
        }
        // A non-string value is kept (and then fails to parse): present but unusable fails closed.
        String text = String.valueOf(value).trim();
        return text.isEmpty() ? null : text;
    }

    /** An EC P-256 public key from base64 DER SubjectPublicKeyInfo, or null (another curve included). */
    @Nullable
    private static PublicKey parsePublicKey(String encoded) {
        try {
            byte[] spki = Base64.decode(encoded, Base64.DEFAULT);
            PublicKey key = KeyFactory.getInstance("EC").generatePublic(new X509EncodedKeySpec(spki));
            if (!(key instanceof ECPublicKey) || !P256_ORDER.equals(((ECPublicKey) key).getParams().getOrder())) {
                return null;
            }
            return key;
        } catch (IllegalArgumentException | GeneralSecurityException ex) {
            return null;
        }
    }

    /** Whether {@code signature} (base64 of the raw 64-byte r‖s) verifies over {@code payload}. */
    private static boolean isValidSignature(PublicKey key, byte[] payload, @Nullable String signature) {
        if (signature == null) {
            return false;
        }
        try {
            byte[] der = rawSignatureToDer(Base64.decode(signature, Base64.DEFAULT));
            if (der == null) {
                return false;
            }
            Signature verifier = Signature.getInstance("SHA256withECDSA");
            verifier.initVerify(key);
            verifier.update(payload);
            return verifier.verify(der);
        } catch (IllegalArgumentException | GeneralSecurityException ex) {
            return false;
        }
    }

    /**
     * WebCrypto's raw r‖s (32 + 32 bytes) as the ASN.1 DER {@code SEQUENCE { INTEGER r, INTEGER s }}
     * that {@code SHA256withECDSA} verifies (the P1363 algorithm name needs API 33). Null unless
     * {@code raw} is 64 bytes.
     */
    @Nullable
    static byte[] rawSignatureToDer(byte[] raw) {
        if (raw.length != 64) {
            return null;
        }
        byte[] r = derInteger(raw, 0);
        byte[] s = derInteger(raw, 32);
        // At most 2 × 35 bytes, so the short length form always fits.
        byte[] der = new byte[2 + r.length + s.length];
        der[0] = 0x30;
        der[1] = (byte) (r.length + s.length);
        System.arraycopy(r, 0, der, 2, r.length);
        System.arraycopy(s, 0, der, 2 + r.length, s.length);
        return der;
    }

    /** The 32 bytes at {@code offset} as a DER INTEGER: leading zeros stripped, 0x00 prepended when the high bit is set. */
    private static byte[] derInteger(byte[] raw, int offset) {
        int start = offset;
        int end = offset + 32;
        while (start < end - 1 && raw[start] == 0) {
            start++;
        }
        boolean pad = (raw[start] & 0x80) != 0;
        int length = end - start + (pad ? 1 : 0);
        byte[] out = new byte[2 + length];
        out[0] = 0x02;
        out[1] = (byte) length;
        System.arraycopy(raw, start, out, pad ? 3 : 2, end - start);
        return out;
    }

    /**
     * A forward-slash path that stays inside its directory: no empty, "." or ".." segments, no
     * backslashes, and no control characters (U+0000–U+001F, U+007F, which could forge the lines
     * the version hashes).
     */
    static boolean isSafeRelativePath(@Nullable String path) {
        if (path == null || path.isEmpty()) {
            return false;
        }
        for (int i = 0; i < path.length(); i++) {
            char c = path.charAt(i);
            if (c < 0x20 || c == 0x7f || c == '\\') {
                return false;
            }
        }
        for (String segment : path.split("/", -1)) {
            if (segment.isEmpty() || segment.equals(".") || segment.equals("..")) {
                return false;
            }
        }
        return true;
    }

    @Nullable
    synchronized String current() {
        return prefs.getString(KEY_CURRENT, null);
    }

    @Nullable
    synchronized String pending() {
        return prefs.getString(KEY_PENDING, null);
    }

    @Nullable
    synchronized String rejected() {
        return prefs.getString(KEY_REJECTED, null);
    }

    /** The staged version, while its verified directory is still there. */
    @Nullable
    synchronized String staged() {
        String staged = prefs.getString(KEY_STAGED, null);
        return hasVersion(staged) ? staged : null;
    }

    /**
     * Records a verified version as staged (and its {@code sequence} as accepted), deleting the
     * directory of the version it replaces unless that one is current, pending or bundled.
     */
    synchronized void stage(String version, @Nullable Long sequence) {
        String old = prefs.getString(KEY_STAGED, null);
        if (
            old != null &&
            !old.equals(version) &&
            !old.equals(prefs.getString(KEY_CURRENT, null)) &&
            !old.equals(prefs.getString(KEY_PENDING, null)) &&
            !old.equals(bundledVersion())
        ) {
            discard(versionDirectory(old));
        }
        // Freshly downloaded and verified: a quarantine of an earlier copy no longer applies.
        installed.remove(version);
        quarantined.remove(version);
        SharedPreferences.Editor editor = prefs.edit().putString(KEY_STAGED, version);
        Long highest = highestSequence();
        if (sequence != null && (highest == null || sequence > highest)) {
            editor.putLong(KEY_SEQUENCE, sequence);
        }
        editor.commit();
    }

    /** The version stamped into the bundled UI ({@code public/_denext/ota.json}), if any. */
    @Nullable
    synchronized String bundledVersion() {
        if (!bundledVersionRead) {
            bundledVersionRead = true;
            JSONObject manifest = parseManifest(readAsset(BUNDLED_ASSET_DIR + "/" + MANIFEST_PATH));
            String version = manifest == null ? null : manifest.optString("version", null);
            bundledVersion = isSha256(version) ? version : null;
        }
        return bundledVersion;
    }

    File versionDirectory(String version) {
        return new File(root, version);
    }

    private boolean hasVersion(@Nullable String version) {
        return version != null && new File(versionDirectory(version), "index.html").isFile();
    }

    /**
     * The directory {@link DenextOta#prepare} starts the bridge from. The first call in a process
     * is the launch ({@link #prepareLaunch}); an activity recreated later in the same process (a
     * rotation, say) keeps serving the active UI, a trial included, instead of counting as a
     * second launch.
     */
    @Nullable
    synchronized File startDirectory() {
        String version;
        // Only the launch itself counts a trial attempt (prepareLaunch).
        boolean counted = !launchPrepared;
        if (!launchPrepared) {
            launchPrepared = true;
            version = prepareLaunch();
        } else {
            String pending = prefs.getString(KEY_PENDING, null);
            launchIsTrial = pending != null && hasVersion(pending);
            String current = prefs.getString(KEY_CURRENT, null);
            version = launchIsTrial ? pending : hasVersion(current) ? current : null;
        }
        // Re-verify before the first page: the stored manifest's signature and version. A version
        // that fails is quarantined, and the confirmed one (re-verified too) or the bundled UI is
        // served instead. The files themselves are checked as they are served (Routes).
        while (version != null) {
            try {
                installedUi(version);
                started = versionDirectory(version);
                return started;
            } catch (OtaException ex) {
                String current = prefs.getString(KEY_CURRENT, null);
                if (UNAVAILABLE.equals(ex.code)) {
                    // There but not readable right now (an I/O or permission error, storage not
                    // available yet): not a change to the UI. Serve something else for this launch
                    // only, give a trial its attempt back, and check the version again at the next
                    // launch. Nothing is quarantined.
                    Logger.warn("denext OTA: UI " + version + " cannot be read now (" + ex.getMessage() + "); not serving it this launch.");
                    if (launchIsTrial && counted) {
                        int attempts = prefs.getInt(KEY_TRIAL_ATTEMPTS, 0);
                        prefs.edit().putInt(KEY_TRIAL_ATTEMPTS, Math.max(0, attempts - 1)).commit();
                    }
                    launchIsTrial = false;
                    version = !version.equals(current) && hasVersion(current) ? current : null;
                    continue;
                }
                report(version, ex.getMessage(), false);
                launchIsTrial = false;
                version = hasVersion(current) ? current : null;
            }
        }
        started = null;
        return null;
    }

    /**
     * Called once per launch, before the bridge loads the first page. Returns the version to serve
     * before re-verification (null: the bundled UI) and sets {@link #launchIsTrial} when this
     * launch is a pending version's trial.
     */
    @Nullable
    private String prepareLaunch() {
        launchIsTrial = false;
        // A new app binary brings its own bundled UI (and maybe new native code), so a UI
        // downloaded for the old binary is dropped, as Capacitor drops its own deploy path.
        String binaryVersion = binaryVersion();
        if (!binaryVersion.equals(prefs.getString(KEY_BINARY_VERSION, null))) {
            reset();
            prefs.edit().putString(KEY_BINARY_VERSION, binaryVersion).commit();
            return null;
        }
        String pending = prefs.getString(KEY_PENDING, null);
        if (pending != null) {
            int attempts = prefs.getInt(KEY_TRIAL_ATTEMPTS, 0);
            if (hasVersion(pending) && attempts < MAX_TRIAL_ATTEMPTS) {
                // One more try: the app died before this version confirmed its boot, which may
                // not be the version's fault (the system kills backgrounded apps).
                prefs.edit().putInt(KEY_TRIAL_ATTEMPTS, attempts + 1).commit();
                launchIsTrial = true;
                return pending;
            }
            // Out of tries (or the files are gone): roll back before loading.
            Logger.warn("denext OTA: UI " + pending + " never confirmed its boot; rolling back.");
            File previous = rollBackPending();
            return previous == null ? null : previous.getName();
        }
        String current = prefs.getString(KEY_CURRENT, null);
        if (current != null) {
            if (hasVersion(current)) {
                return current;
            }
            prefs.edit().remove(KEY_CURRENT).commit();
        }
        return null;
    }

    // Re-verification ------------------------------------------------------------------------

    /** What {@link InstalledUi#check} decided about one file. */
    enum Verdict {
        /** The file matches the signed manifest: serve it. */
        SERVE,
        /** Not a file of this UI, and nothing is there: refuse it (the request fails, as it would). */
        MISSING,
        /** The UI was changed on the device after it was downloaded: never serve it. */
        TAMPERED,
        /**
         * The file is there but cannot be read right now (an I/O or permission error, storage not
         * available yet): refuse this request without quarantining, and check it again the next
         * time it is asked for.
         */
        UNAVAILABLE
    }

    /**
     * A downloaded UI as its stored manifest describes it, once that manifest re-verified
     * ({@link #verifyInstalled}); {@link #check} verifies each file the first time it is served.
     */
    static final class InstalledUi {

        final String version;
        final File directory;
        private final Map<String, ManifestFile> files = new HashMap<>();
        private final String manifestSha256;
        /** The paths whose bytes already matched in this process. */
        private final Set<String> verified = ConcurrentHashMap.newKeySet();

        InstalledUi(String version, File directory, List<ManifestFile> files, String manifestSha256) {
            this.version = version;
            this.directory = directory;
            for (ManifestFile file : files) {
                this.files.put(file.path, file);
            }
            this.manifestSha256 = manifestSha256;
        }

        /**
         * Whether {@code relative} (a path inside the UI, as requested) may be served. A file of the
         * manifest is hashed the first time (SHA-256 and size); the manifest itself must still be
         * the bytes verified at launch; any other file that exists was added on the device.
         */
        Verdict check(String relative) {
            if (relative.equals(MANIFEST_PATH)) {
                byte[] data;
                try {
                    data = readStored(new File(directory, MANIFEST_PATH));
                } catch (OtaException ex) {
                    return Verdict.UNAVAILABLE;
                }
                return data != null && sha256Hex(data).equals(manifestSha256) ? Verdict.SERVE : Verdict.TAMPERED;
            }
            if (!isSafeRelativePath(relative)) {
                return Verdict.MISSING;
            }
            File target = new File(directory, relative);
            ManifestFile file = files.get(relative);
            if (file == null) {
                return target.exists() ? Verdict.TAMPERED : Verdict.MISSING;
            }
            if (verified.contains(relative)) {
                return Verdict.SERVE;
            }
            Verdict verdict = compare(target, file);
            if (verdict == Verdict.SERVE) {
                verified.add(relative);
            }
            return verdict;
        }

        /** Whether the signed manifest lists {@code relative}. */
        boolean lists(String relative) {
            return files.containsKey(relative);
        }
    }

    /**
     * Re-verifies the downloaded UI {@code version} in {@code directory} from the manifest stored
     * with its files: well formed, the same version, the version recomputed from the file list,
     * and with {@code encodedKey} (the {@link #PUBLIC_KEY_META} value) set, a signature that
     * verifies over the stored fields (a key that does not parse fails closed). Throws
     * {@code integrity} / {@code signature} / {@code invalid}, or {@code unavailable} when the
     * manifest is there but cannot be read right now ({@link #readStored}), which is not a verdict
     * on the UI; the files are checked by {@link InstalledUi#check} as they are served.
     */
    static InstalledUi verifyInstalled(File directory, String version, @Nullable String encodedKey) throws OtaException {
        byte[] data = readStored(new File(directory, MANIFEST_PATH));
        JSONObject manifest = parseManifest(data);
        if (data == null || manifest == null || !version.equals(manifest.opt("version"))) {
            throw new OtaException("integrity", "UI " + version + "'s stored manifest is missing or names another version.");
        }
        List<ManifestFile> files = parseFiles(manifest.optJSONArray("files"));
        Long sequence = releaseInteger(manifest.opt("sequence"), "sequence");
        Long minNative = releaseInteger(manifest.opt("minNative"), "minNative");
        String nativeFingerprint = fingerprintField(manifest.opt("nativeFingerprint"));
        if (!manifestVersion(files).equals(version)) {
            throw new OtaException("integrity", "UI " + version + "'s stored manifest does not match its version.");
        }
        if (encodedKey != null) {
            PublicKey key = parsePublicKey(encodedKey);
            if (key == null) {
                throw new OtaException("signature", "The " + PUBLIC_KEY_META + " meta-data is not a base64 P-256 public key.");
            }
            Object notes = manifest.opt("notes");
            Object signature = manifest.opt("signature");
            byte[] payload = signaturePayload(
                version,
                Boolean.TRUE.equals(manifest.opt("required")),
                notes instanceof String ? (String) notes : "",
                sequence,
                minNative,
                nativeFingerprint
            );
            if (!isValidSignature(key, payload, signature instanceof String ? (String) signature : null)) {
                throw new OtaException("signature", "UI " + version + "'s stored manifest signature does not verify.");
            }
        }
        return new InstalledUi(version, directory, files, sha256Hex(data));
    }

    /** Told when a UI is quarantined: its version, why, and whether it was being served. */
    interface TamperListener {
        void onTampered(String version, String reason, boolean serving);
    }

    /** The re-verified UIs of this process, by version. */
    private final Map<String, InstalledUi> installed = new HashMap<>();
    /** The versions quarantined in this process. */
    private final Set<String> quarantined = new HashSet<>();
    @Nullable
    private TamperListener tamperListener;
    /** Quarantines that happened before the plugin set its listener (at launch): version, reason. */
    private final List<String[]> unreported = new ArrayList<>();
    /** The bridge the plugin loaded into, whose served directory {@link Routes} reads. */
    @Nullable
    private volatile Bridge bridge;
    /** The directory {@link #startDirectory} last chose, for a request before the plugin attached the bridge. */
    @Nullable
    private volatile File started;
    private final Routes routes = new Routes(this);

    /** The re-verified UI for {@code version}, verifying its stored manifest the first time. */
    synchronized InstalledUi installedUi(String version) throws OtaException {
        if (quarantined.contains(version)) {
            throw new OtaException("integrity", "UI " + version + " was quarantined.");
        }
        InstalledUi ui = installed.get(version);
        if (ui == null) {
            ui = verifyInstalled(versionDirectory(version), version, publicKeyMetaData());
            installed.put(version, ui);
        }
        return ui;
    }

    /** The route processor {@link DenextOta#prepare} gives the bridge. */
    RouteProcessor routes() {
        return routes;
    }

    /** Called by the plugin as the bridge loads it (before the first page), and sets its listener. */
    void attach(Bridge bridge, TamperListener listener) {
        this.bridge = bridge;
        List<String[]> earlier;
        synchronized (this) {
            tamperListener = listener;
            earlier = new ArrayList<>(unreported);
            unreported.clear();
        }
        for (String[] event : earlier) {
            listener.onTampered(event[0], event[1], false);
        }
    }

    /** The last downloaded version that failed re-verification, or null (cleared by {@code reset}). */
    @Nullable
    synchronized String tampered() {
        return prefs.getString(KEY_TAMPERED, null);
    }

    /**
     * The directory to serve once a UI was quarantined: the confirmed version when it is still
     * there and re-verifies, else null for the bundled UI.
     */
    @Nullable
    synchronized File fallbackDirectory() {
        String current = prefs.getString(KEY_CURRENT, null);
        if (!hasVersion(current)) {
            return null;
        }
        try {
            installedUi(current);
            return versionDirectory(current);
        } catch (OtaException ex) {
            return null;
        }
    }

    /**
     * Whether the local server may read {@code path} (a request path) from {@code served}, the
     * directory the bridge serves. Anything outside a downloaded UI passes. Inside one, the file
     * must match the signed manifest ({@link InstalledUi#check}); a mismatch quarantines the
     * version and tells the plugin, which switches the webview away. Any thread.
     */
    boolean admit(String served, String path) {
        String rootPath = root.getPath();
        if (!served.equals(rootPath) && !served.startsWith(rootPath + "/")) {
            return true;
        }
        // Under the versions root, only a version directory is ever served.
        File base = new File(served);
        String version = base.getName();
        if (!rootPath.equals(base.getParent()) || !isSha256(version)) {
            return false;
        }
        String relative = path.startsWith("/") ? path.substring(1) : path;
        // The directory itself: the server cannot read it, so the request fails anyway.
        if (relative.isEmpty()) {
            return true;
        }
        InstalledUi ui;
        try {
            ui = installedUi(version);
        } catch (OtaException ex) {
            if (!UNAVAILABLE.equals(ex.code)) {
                report(version, ex.getMessage(), true);
            }
            return false;
        }
        Verdict verdict = ui.check(relative);
        if (verdict == Verdict.TAMPERED) {
            String why = relative.equals(MANIFEST_PATH)
                ? " changed after it was verified."
                : ui.lists(relative) ? " does not match the signed manifest." : " is not in the signed manifest.";
            report(version, relative + why, true);
        }
        return verdict == Verdict.SERVE;
    }

    /** Quarantines {@code version} and tells the plugin (later, once it is attached, for a launch). */
    private void report(String version, String reason, boolean serving) {
        TamperListener listener;
        synchronized (this) {
            if (!quarantine(version, reason)) {
                return;
            }
            listener = tamperListener;
            if (listener == null) {
                unreported.add(new String[] { version, reason });
                return;
            }
        }
        listener.onTampered(version, reason, serving);
    }

    /**
     * Takes {@code version} out of service after it failed re-verification: it stops being
     * current, pending or staged, is remembered as {@code tampered}, and its directory moves to
     * {@code quarantine/} (which keeps only the latest; {@code reset} and the next confirmed update
     * delete it). It is not {@code rejected}: the server's copy is fine, so downloading it again is
     * allowed. Returns false when this process already quarantined it.
     */
    synchronized boolean quarantine(String version, String reason) {
        installed.remove(version);
        if (!quarantined.add(version)) {
            return false;
        }
        Logger.warn("denext OTA: UI " + version + " failed re-verification (" + reason + "); not serving it.");
        SharedPreferences.Editor editor = prefs.edit().putString(KEY_TAMPERED, version);
        if (version.equals(prefs.getString(KEY_CURRENT, null))) {
            editor.remove(KEY_CURRENT);
        }
        if (version.equals(prefs.getString(KEY_PENDING, null))) {
            editor.remove(KEY_PENDING).remove(KEY_PREVIOUS).remove(KEY_TRIAL_ATTEMPTS).remove(KEY_LEGACY_TRIAL_STARTED);
        }
        if (version.equals(prefs.getString(KEY_STAGED, null))) {
            editor.remove(KEY_STAGED);
        }
        editor.commit();
        File quarantine = new File(root, QUARANTINE_DIR);
        discard(quarantine);
        File directory = versionDirectory(version);
        if (!quarantine.mkdirs() || !directory.renameTo(new File(quarantine, version))) {
            discard(directory);
        }
        return true;
    }

    /**
     * The bridge's route processor: the local server asks it for the file behind every request.
     * While the bundled assets are served it answers as Capacitor would without one; while a
     * directory is served (a downloaded UI) it answers with the file under that directory once
     * {@link #admit} accepts it, else with the directory itself, which the server cannot read
     * (the request fails). Capacitor's {@code /_capacitor_file_} and {@code /_capacitor_content_}
     * paths pass through.
     */
    static final class Routes implements RouteProcessor {

        private final DenextOtaStore store;

        Routes(DenextOtaStore store) {
            this.store = store;
        }

        @Override
        public ProcessedRoute process(String basePath, String path) {
            ProcessedRoute route = new ProcessedRoute();
            Bridge bridge = store.bridge;
            File started = store.started;
            String served = bridge != null ? bridge.getServerBasePath() : started == null ? null : started.getAbsolutePath();
            boolean files = served != null && served.startsWith("/");
            route.setAsset(!files);
            if (!files) {
                // The local server adds the asset directory itself (and passes it as basePath for index.html).
                route.setPath(basePath + path);
            } else if (path.startsWith(Bridge.CAPACITOR_FILE_START) || path.startsWith(Bridge.CAPACITOR_CONTENT_START)) {
                route.setPath(path);
            } else {
                route.setPath(store.admit(served, path) ? served + path : served);
            }
            return route;
        }
    }

    /**
     * {@code activate} / {@code apply}: the (staged) version starts its trial, which counts as its
     * first attempt; nothing stays staged.
     */
    synchronized void beginTrial(String version) {
        prefs
            .edit()
            .putString(KEY_PREVIOUS, prefs.getString(KEY_CURRENT, null))
            .putString(KEY_PENDING, version)
            .putInt(KEY_TRIAL_ATTEMPTS, 1)
            .remove(KEY_LEGACY_TRIAL_STARTED)
            .remove(KEY_STAGED)
            .commit();
    }

    /** {@code booted}: the pending version becomes current, and every other version is deleted (bar a staged one). */
    synchronized void confirmPending() {
        String pending = prefs.getString(KEY_PENDING, null);
        if (pending == null) {
            return;
        }
        String staged = prefs.getString(KEY_STAGED, null);
        prefs
            .edit()
            .putString(KEY_CURRENT, pending)
            .remove(KEY_PENDING)
            .remove(KEY_PREVIOUS)
            .remove(KEY_TRIAL_ATTEMPTS)
            .remove(KEY_LEGACY_TRIAL_STARTED)
            .commit();
        File[] entries = root.listFiles();
        if (entries != null) {
            for (File entry : entries) {
                if (!entry.getName().equals(pending) && !entry.getName().equals(staged)) {
                    discard(entry);
                }
            }
        }
    }

    /**
     * Drops the pending version (remembered as rejected) and returns the directory to serve: the
     * previous version if it is still there, otherwise null for the bundled UI.
     */
    @Nullable
    synchronized File rollBackPending() {
        String previous = prefs.getString(KEY_PREVIOUS, null);
        String target = hasVersion(previous) ? previous : null;
        String failed = prefs.getString(KEY_PENDING, null);
        SharedPreferences.Editor editor = prefs.edit();
        if (failed != null) {
            editor.putString(KEY_REJECTED, failed);
            discard(versionDirectory(failed));
        }
        editor.remove(KEY_PENDING).remove(KEY_PREVIOUS).remove(KEY_TRIAL_ATTEMPTS).remove(KEY_LEGACY_TRIAL_STARTED);
        if (target == null) {
            editor.remove(KEY_CURRENT);
        } else {
            editor.putString(KEY_CURRENT, target);
        }
        editor.commit();
        return target == null ? null : versionDirectory(target);
    }

    /**
     * Back to the bundled UI with no downloaded or staged versions and nothing rejected. The
     * accepted {@code sequence} is kept: downgrade protection outlives a reset.
     */
    synchronized void reset() {
        prefs
            .edit()
            .remove(KEY_CURRENT)
            .remove(KEY_PENDING)
            .remove(KEY_PREVIOUS)
            .remove(KEY_TRIAL_ATTEMPTS)
            .remove(KEY_LEGACY_TRIAL_STARTED)
            .remove(KEY_REJECTED)
            .remove(KEY_STAGED)
            .remove(KEY_TAMPERED)
            .commit();
        discard(root);
        installed.clear();
        quarantined.clear();
    }

    /**
     * Renames {@code file} out of the way (instant) and deletes it on a background thread, so no
     * recursive delete runs on the caller's (often the main) thread.
     */
    private static void discard(File file) {
        if (!file.exists()) {
            return;
        }
        File trash = new File(file.getParentFile(), TRASH_PREFIX + UUID.randomUUID());
        final File target = file.renameTo(trash) ? trash : file;
        JANITOR.execute(() -> deleteRecursively(target));
    }

    /** Deletes, in the background, what an earlier process discarded but did not finish deleting. */
    private static void sweepTrash(@Nullable File directory) {
        File[] entries = directory == null ? null : directory.listFiles();
        if (entries == null) {
            return;
        }
        for (File entry : entries) {
            if (entry.getName().startsWith(TRASH_PREFIX)) {
                JANITOR.execute(() -> deleteRecursively(entry));
            }
        }
    }

    /** The running download (if any), then the bundled UI. */
    private List<LocalSource> localSources() {
        List<LocalSource> sources = new ArrayList<>();
        String current = current();
        if (hasVersion(current)) {
            final File directory = versionDirectory(current);
            final Map<String, String> index = indexOf(parseManifest(readFile(new File(directory, MANIFEST_PATH))));
            sources.add(
                new LocalSource() {
                    @Override
                    public InputStream open(String path) {
                        try {
                            return new FileInputStream(new File(directory, path));
                        } catch (IOException ex) {
                            return null;
                        }
                    }

                    @Override
                    public Map<String, String> pathsBySha() {
                        return index;
                    }
                }
            );
        }
        final Map<String, String> bundledIndex = indexOf(parseManifest(readAsset(BUNDLED_ASSET_DIR + "/" + MANIFEST_PATH)));
        sources.add(
            new LocalSource() {
                @Override
                public InputStream open(String path) {
                    try {
                        return context.getAssets().open(BUNDLED_ASSET_DIR + "/" + path);
                    } catch (IOException ex) {
                        return null;
                    }
                }

                @Override
                public Map<String, String> pathsBySha() {
                    return bundledIndex;
                }
            }
        );
        return sources;
    }

    /**
     * Copies {@code file} into {@code temp} from a UI already on the device that has a file with
     * the same SHA-256 (by its manifest, or at the same path), verifying the bytes as they stream.
     */
    private static boolean copyLocal(ManifestFile file, List<LocalSource> sources, File temp) {
        for (LocalSource source : sources) {
            List<String> candidates = new ArrayList<>();
            String byHash = source.pathsBySha().get(file.sha256);
            if (byHash != null && isSafeRelativePath(byHash)) {
                candidates.add(byHash);
            }
            if (!candidates.contains(file.path)) {
                candidates.add(file.path);
            }
            for (String candidate : candidates) {
                InputStream input = source.open(candidate);
                if (input != null && copyVerified(input, temp, file)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Streams {@code input} (closing it) into {@code target} while hashing it; true when the bytes match {@code file}. */
    private static boolean copyVerified(InputStream input, File target, ManifestFile file) {
        MessageDigest digest = sha256();
        long size = 0;
        boolean ok = true;
        try (InputStream in = input; OutputStream out = new FileOutputStream(target)) {
            byte[] buffer = new byte[65_536];
            int read;
            while ((read = in.read(buffer)) != -1) {
                size += read;
                if (size > file.size) {
                    ok = false;
                    break;
                }
                digest.update(buffer, 0, read);
                out.write(buffer, 0, read);
            }
        } catch (IOException ex) {
            ok = false;
        }
        ok = ok && size == file.size && hex(digest.digest()).equals(file.sha256);
        if (!ok) {
            //noinspection ResultOfMethodCallIgnored
            target.delete();
        }
        return ok;
    }

    /** Whether the file at {@code path} has {@code file}'s size and SHA-256 (read in chunks). */
    private static boolean matches(File path, ManifestFile file) {
        return compare(path, file) == Verdict.SERVE;
    }

    /**
     * {@link Verdict#SERVE} when the file at {@code path} has {@code file}'s size and SHA-256 (read
     * in chunks), {@link Verdict#UNAVAILABLE} when it is there but cannot be read right now, else
     * {@link Verdict#TAMPERED}.
     */
    private static Verdict compare(File path, ManifestFile file) {
        if (!path.isFile() || path.length() != file.size) {
            return Verdict.TAMPERED;
        }
        MessageDigest digest = sha256();
        try (InputStream in = new FileInputStream(path)) {
            byte[] buffer = new byte[65_536];
            int read;
            while ((read = in.read(buffer)) != -1) {
                digest.update(buffer, 0, read);
            }
        } catch (IOException ex) {
            return Verdict.UNAVAILABLE;
        }
        return hex(digest.digest()).equals(file.sha256) ? Verdict.SERVE : Verdict.TAMPERED;
    }

    /** Stops the download in flight (from any thread): it fails with code download at its next step. */
    void cancelDownload() {
        cancelRequested = true;
        disconnectAll();
    }

    private void checkCancelled() throws OtaException {
        if (cancelRequested || Thread.currentThread().isInterrupted()) {
            throw new OtaException("download", "The UI download was cancelled.");
        }
    }

    private void disconnectAll() {
        List<HttpURLConnection> open;
        synchronized (connections) {
            open = new ArrayList<>(connections);
        }
        for (HttpURLConnection connection : open) {
            connection.disconnect();
        }
    }

    /** Deletes the {@code .partial} / {@code .tmp} directories of other versions: only the version being downloaded may resume. */
    private void removeStaleAttempts(String version) {
        File[] entries = root.listFiles();
        if (entries == null) {
            return;
        }
        for (File entry : entries) {
            String name = entry.getName();
            boolean attempt = name.endsWith(".partial") || name.endsWith(".tmp");
            if (attempt && !name.equals(version + ".partial") && !name.equals(version + ".tmp")) {
                discard(entry);
            }
        }
    }

    /**
     * Off the main thread. Fetches and verifies every file into {@code <version>.partial/} (copying
     * the ones a UI on the device already has, and keeping the ones an interrupted attempt already
     * verified there), writes the manifest next to them, then renames the directory to
     * {@code <version>/}. A failure keeps the verified files for the next attempt. Each file streams
     * to disk while it is hashed and is refused as soon as it outgrows its manifest {@code size}.
     * The whole call is bounded by {@link #APPLY_DEADLINE_MS} and stops early on {@link #cancelDownload}.
     */
    DownloadStats download(ApplyRequest request) throws OtaException {
        cancelRequested = false;
        long deadline = System.currentTimeMillis() + APPLY_DEADLINE_MS;
        removeStaleAttempts(request.version);
        File partial = new File(root, request.version + ".partial");
        File scratch = new File(root, request.version + ".tmp");
        File destination = versionDirectory(request.version);
        if ((!partial.isDirectory() && !partial.mkdirs()) || (!scratch.isDirectory() && !scratch.mkdirs())) {
            throw new OtaException("download", "Could not create " + partial);
        }
        ExecutorService pool = Executors.newFixedThreadPool(MAX_CONCURRENT_DOWNLOADS);
        try {
            final List<LocalSource> sources = localSources();
            List<Future<Boolean>> futures = new ArrayList<>();
            for (ManifestFile file : request.files) {
                futures.add(pool.submit(() -> fetchFile(file, request, sources, partial, scratch)));
            }
            DownloadStats stats = new DownloadStats();
            for (Future<Boolean> future : futures) {
                long wait = deadline - System.currentTimeMillis();
                if (wait <= 0) {
                    throw new TimeoutException();
                }
                if (future.get(wait, TimeUnit.MILLISECONDS)) {
                    stats.copied++;
                } else {
                    stats.downloaded++;
                }
            }
            checkCancelled();
            writeManifest(request, partial);
            discard(destination);
            if (!partial.renameTo(destination)) {
                throw new OtaException("download", "Could not move the UI into place.");
            }
            discard(scratch);
            return stats;
        } catch (TimeoutException ex) {
            stop(pool);
            throw new OtaException("download", "The UI update took longer than " + APPLY_DEADLINE_MS / 60_000 + " minutes.");
        } catch (ExecutionException ex) {
            stop(pool);
            Throwable cause = ex.getCause();
            if (cause instanceof OtaException) {
                throw (OtaException) cause;
            }
            throw new OtaException("download", cause == null ? ex.toString() : cause.toString());
        } catch (InterruptedException ex) {
            stop(pool);
            Thread.currentThread().interrupt();
            throw new OtaException("download", "The UI download was interrupted.");
        } catch (IOException | JSONException ex) {
            stop(pool);
            throw new OtaException("download", ex.toString());
        } finally {
            // Always first: no worker may still be writing when anything is renamed or deleted.
            stop(pool);
        }
    }

    /** Stops every worker of {@code pool} (interrupting and disconnecting them) and waits for them to finish. */
    private void stop(ExecutorService pool) {
        pool.shutdownNow();
        disconnectAll();
        try {
            pool.awaitTermination(10, TimeUnit.SECONDS);
        } catch (InterruptedException ex) {
            Thread.currentThread().interrupt();
        }
    }

    /**
     * The version's own {@code _denext/ota.json}, so a later update can copy files from it, the page
     * can read its version, and every launch can verify the signature and the files again
     * ({@link #verifyInstalled}): it keeps every field the signature covers.
     */
    private static void writeManifest(ApplyRequest request, File directory) throws IOException, JSONException {
        JSONArray files = new JSONArray();
        for (ManifestFile file : request.files) {
            files.put(new JSONObject().put("path", file.path).put("sha256", file.sha256).put("size", file.size));
        }
        JSONObject manifest = new JSONObject()
            .put("version", request.version)
            .put("files", files)
            .put("required", request.required)
            .put("notes", request.notes);
        if (request.sequence != null) {
            manifest.put("sequence", (long) request.sequence);
        }
        if (request.minNative != null) {
            manifest.put("minNative", (long) request.minNative);
        }
        if (request.nativeFingerprint != null) {
            manifest.put("nativeFingerprint", request.nativeFingerprint);
        }
        if (request.signature != null) {
            manifest.put("signature", request.signature);
        }
        File target = new File(directory, MANIFEST_PATH);
        File parent = target.getParentFile();
        if (parent != null && !parent.isDirectory() && !parent.mkdirs() && !parent.isDirectory()) {
            throw new IOException("Could not create " + parent);
        }
        try (OutputStream output = new FileOutputStream(target)) {
            output.write(manifest.toString().getBytes(StandardCharsets.UTF_8));
        }
    }

    /**
     * Puts one verified file at its path in {@code directory}; returns true when it was already
     * there from an earlier attempt or copied from the device, false when it was downloaded.
     */
    private boolean fetchFile(ManifestFile file, ApplyRequest request, List<LocalSource> sources, File directory, File scratch)
        throws OtaException, IOException {
        checkCancelled();
        File target = new File(directory, file.path);
        if (!target.getCanonicalPath().startsWith(directory.getCanonicalPath() + File.separator)) {
            throw new OtaException("invalid", file.path + " leaves the UI directory.");
        }
        if (matches(target, file)) {
            return true;
        }
        File temp = new File(scratch, UUID.randomUUID().toString());
        try {
            boolean copied = copyLocal(file, sources, temp);
            if (!copied) {
                downloadFile(file, request, temp);
            }
            File parent = target.getParentFile();
            if (parent != null && !parent.isDirectory() && !parent.mkdirs() && !parent.isDirectory()) {
                throw new IOException("Could not create " + parent);
            }
            if ((target.exists() && !target.delete()) || !temp.renameTo(target)) {
                throw new IOException("Could not move " + file.path + " into place.");
            }
            return copied;
        } finally {
            //noinspection ResultOfMethodCallIgnored
            temp.delete();
        }
    }

    /** Streams {@code file} from the server into {@code temp}, verifying its size and SHA-256 as it arrives. */
    private void downloadFile(ManifestFile file, ApplyRequest request, File temp) throws OtaException, IOException {
        Uri.Builder uri = Uri.parse(request.baseUrl).buildUpon();
        for (String segment : file.path.split("/")) {
            uri.appendPath(segment);
        }
        long deadline = System.currentTimeMillis() + fileDeadlineMs(file.size);
        HttpURLConnection connection = open(new URL(uri.build().toString()), request, file);
        try {
            long length = connection.getContentLengthLong();
            if (length > file.size) {
                throw new OtaException("integrity", file.path + " is larger than the manifest says.");
            }
            MessageDigest digest = sha256();
            long received = 0;
            try (InputStream input = connection.getInputStream(); OutputStream output = new FileOutputStream(temp)) {
                byte[] buffer = new byte[65_536];
                int read;
                while ((read = input.read(buffer)) != -1) {
                    checkCancelled();
                    received += read;
                    if (received > file.size) {
                        throw new OtaException("integrity", file.path + " is larger than the manifest says.");
                    }
                    if (System.currentTimeMillis() > deadline) {
                        throw new OtaException("download", "Downloading " + file.path + " took longer than " + fileDeadlineMs(file.size) / 1000 + " s.");
                    }
                    digest.update(buffer, 0, read);
                    output.write(buffer, 0, read);
                }
            }
            if (received != file.size || !hex(digest.digest()).equals(file.sha256)) {
                throw new OtaException("integrity", file.path + " does not match the manifest.");
            }
        } finally {
            connections.remove(connection);
            connection.disconnect();
        }
    }

    /**
     * Opens {@code url} with the request headers, following redirects only within the base URL's
     * origin (the headers, which may carry a bearer token, never reach another origin), and
     * returns the connection once it answered 200.
     */
    private HttpURLConnection open(URL url, ApplyRequest request, ManifestFile file) throws OtaException, IOException {
        URL base = new URL(request.baseUrl);
        URL current = url;
        for (int hop = 0; ; hop++) {
            checkCancelled();
            HttpURLConnection connection = (HttpURLConnection) current.openConnection();
            connections.add(connection);
            connection.setInstanceFollowRedirects(false);
            connection.setConnectTimeout(IDLE_TIMEOUT_MS);
            connection.setReadTimeout(IDLE_TIMEOUT_MS);
            connection.setUseCaches(false);
            for (Map.Entry<String, String> header : request.headers.entrySet()) {
                connection.setRequestProperty(header.getKey(), header.getValue());
            }
            int status = connection.getResponseCode();
            if (status == 200) {
                return connection;
            }
            String location = connection.getHeaderField("Location");
            connections.remove(connection);
            connection.disconnect();
            boolean redirect = status == 301 || status == 302 || status == 303 || status == 307 || status == 308;
            if (!redirect || location == null) {
                throw new OtaException("download", "Downloading " + file.path + " failed with HTTP " + status + ".");
            }
            if (hop >= MAX_REDIRECTS) {
                throw new OtaException("download", "Downloading " + file.path + " was redirected too often.");
            }
            URL next = new URL(current, location);
            if (!isSameOrigin(next, base)) {
                throw new OtaException("download", "Refusing a redirect to another origin (" + next.getHost() + ").");
            }
            current = next;
        }
    }

    /** Whether {@code a} and {@code b} have the same scheme, host and (effective) port. */
    static boolean isSameOrigin(URL a, URL b) {
        int portA = a.getPort() == -1 ? a.getDefaultPort() : a.getPort();
        int portB = b.getPort() == -1 ? b.getDefaultPort() : b.getPort();
        return a.getProtocol().equalsIgnoreCase(b.getProtocol()) && a.getHost().equalsIgnoreCase(b.getHost()) && portA == portB;
    }

    private String binaryVersion() {
        try {
            PackageInfo info = context.getPackageManager().getPackageInfo(context.getPackageName(), 0);
            // The bundled UI's version is part of the key, so a rebuild that ships a different
            // UI counts as a new binary even when versionName/versionCode were not bumped.
            String bundled = bundledVersion();
            return info.versionName + "+" + PackageInfoCompat.getLongVersionCode(info) + "+"
                + (bundled == null ? "" : bundled);
        } catch (PackageManager.NameNotFoundException ex) {
            return "";
        }
    }

    /** SHA-256 → path from a parsed manifest (empty when there is none). */
    private static Map<String, String> indexOf(@Nullable JSONObject manifest) {
        Map<String, String> index = new HashMap<>();
        JSONArray files = manifest == null ? null : manifest.optJSONArray("files");
        if (files == null) {
            return index;
        }
        for (int i = 0; i < files.length(); i++) {
            JSONObject file = files.optJSONObject(i);
            String sha = file == null ? null : file.optString("sha256", null);
            String path = file == null ? null : file.optString("path", null);
            if (sha != null && path != null && !index.containsKey(sha)) {
                index.put(sha, path);
            }
        }
        return index;
    }

    @Nullable
    private static JSONObject parseManifest(@Nullable byte[] data) {
        if (data == null) {
            return null;
        }
        try {
            return new JSONObject(new String(data, StandardCharsets.UTF_8));
        } catch (JSONException ex) {
            return null;
        }
    }

    @Nullable
    private byte[] readAsset(String path) {
        try (InputStream input = context.getAssets().open(path)) {
            return readAll(input);
        } catch (IOException ex) {
            return null;
        }
    }

    @Nullable
    private static byte[] readFile(File file) {
        if (!file.isFile()) {
            return null;
        }
        try (InputStream input = new FileInputStream(file)) {
            return readAll(input);
        } catch (IOException ex) {
            return null;
        }
    }

    /**
     * The bytes of the stored file {@code file} of a downloaded UI; null when it is missing (or
     * not a regular file). Throws {@code unavailable} when it is there but cannot be read right now.
     */
    @Nullable
    private static byte[] readStored(File file) throws OtaException {
        if (!file.isFile()) {
            return null;
        }
        try (InputStream input = new FileInputStream(file)) {
            return readAll(input);
        } catch (IOException ex) {
            throw new OtaException(UNAVAILABLE, file.getName() + " cannot be read: " + ex.getMessage());
        }
    }

    private static MessageDigest sha256() {
        try {
            return MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException(ex);
        }
    }

    private static String hex(byte[] digest) {
        StringBuilder hex = new StringBuilder(digest.length * 2);
        for (byte value : digest) {
            hex.append(String.format("%02x", value));
        }
        return hex.toString();
    }

    private static String sha256Hex(byte[] data) {
        return hex(sha256().digest(data));
    }

    private static byte[] readAll(InputStream input) throws IOException {
        ByteArrayOutputStream output = new ByteArrayOutputStream();
        byte[] buffer = new byte[65_536];
        int read;
        while ((read = input.read(buffer)) != -1) {
            output.write(buffer, 0, read);
        }
        return output.toByteArray();
    }

    private static void deleteRecursively(File file) {
        File[] children = file.listFiles();
        if (children != null) {
            for (File child : children) {
                deleteRecursively(child);
            }
        }
        //noinspection ResultOfMethodCallIgnored
        file.delete();
    }
}
